// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    Log log_;

    function setUp() public {
        log_ = new Log();
        c = new W_WALLET(address(log_));
    }

    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        amount1 = bound(amount1, 1, 1e30);
        amount2 = bound(amount2, 1, 1e30);

        vm.deal(address(this), amount1 + amount2);

        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);

        // Rule: the k-th successful Put appends History[k-1]; the second
        // entry must record the second deposit's sender and value.
        bool ok;
        address sender2;
        uint256 val2;
        try log_.History(1) returns (address s, string memory, uint256 v, uint256) {
            ok = true;
            sender2 = s;
            val2 = v;
        } catch {
            ok = false;
        }

        assertTrue(ok && sender2 == address(this) && val2 == amount2);
    }
}
